import dashscope
import json
from http import HTTPStatus

def vl_rerank():
  resp = dashscope.TextReRank.call(
    model="qwen3-vl-rerank",
    query={"image": "https://img.alicdn.com/imgextra/i3/O1CN01rdstgY1uiZWt8gqSL_!!6000000006071-0-tps-1970-356.jpg"},
    documents=[
      {"text": "Rerank models are widely used in search engines."},
      {"image": "https://img.alicdn.com/imgextra/i3/O1CN01rdstgY1uiZWt8gqSL_!!6000000006071-0-tps-1970-356.jpg"},
      {"video": "https://help-static-aliyun-doc.aliyuncs.com/file-manage-files/zh-CN/20250107/lbcemt/new+video.mp4"}
    ],
    top_n=2,
    return_documents=True
  )
  if resp.status_code == HTTPStatus.OK:
    print(json.dumps(resp, default=str, ensure_ascii=False, indent=2))
  else:
    print(resp)

if __name__ == '__main__':
  vl_rerank()
